using System;
using DisplayInspector;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[Serializable]
public class CompanionLevel
{
	[Header("Stats")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private int maxCorruption;

	[SerializeField]
	private StartingEffect[] startingEffects = new StartingEffect[0];

	[Header("Dice")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	[DisplayInspector(true)]
	private CompanionDice companionDice;

	public int MaxCorruption => maxCorruption;

	public StartingEffect[] StartingEffects => startingEffects;

	[SerializeField]
	public CompanionDice CompanionDice => companionDice;

	public CompanionLevel(int maxCorruption, StartingEffect[] startingEffects, CompanionDice companionDice)
	{
		this.maxCorruption = maxCorruption;
		this.startingEffects = startingEffects;
		this.companionDice = companionDice;
	}
}
